function correctionValue(s, t) {
    let sumS = 0;
    let sumT = 0;

    // Calculate sum of Unicode values for each string
    for (let i = 0; i < s.length; i++) {
        sumS += s.charCodeAt(i);
    }

    for (let i = 0; i < t.length; i++) {
